40:         clearTimeout(pending.timer); this.pending.delete(message.id);
41:         if (message.error) pending.reject(new Error(message.error.message)); else pending.resolve(message.result);
42:       }
43:     });
44:     const failed = (message: string) => {
45:       if (this.child !== child) return;
46:       this.child = undefined; this.starting = undefined; lines.close();
47:       for (const pending of this.pending.values()) { clearTimeout(pending.timer); pending.reject(new Error(message)); }
48:       this.pending.clear();
49:       for (const listener of this.listeners) listener.exit(message);
50:     };
51:     child.once('error', error => failed(`Cannot start Codex: ${error.message}. Install Codex and run codex login on the server.`));
52:     child.once('exit', () => failed('Codex disconnected. Send another message to resume the conversation.'));
53:     child.stdin.on('error', () => failed('Codex input disconnected.'));
54:     this.starting = this.rpc('initialize', { clientInfo: { name: 'new_diagram', title: 'New Diagram', version: '0.1.0' }, capabilities: { experimentalApi: true } })
55:       .then(() => { this.write({ method: 'initialized' }); }).catch(error => { child.kill(); failed(String(error)); throw error; });
56:     return this.starting;
57:   }
58:   private write(message: unknown) {
59:     if (!this.child?.stdin.writable) throw new Error('Codex is disconnected.');
60:     this.child.stdin.write(`${JSON.stringify(message)}\n`);
61:   }
62:   private rpc<T>(method: string, params: Record<string, unknown>): Promise<T> {
63:     const id = ++this.serial;
64:     return new Promise((resolve, reject) => {
65:       const timer = setTimeout(() => { this.pending.delete(id); reject(new Error(`Codex ${method} timed out.`)); }, 30_000);
66:       this.pending.set(id, { resolve: value => resolve(value as T), reject, timer });
67:       try { this.write({ id, method, params }); } catch (error) { clearTimeout(timer); this.pending.delete(id); reject(error); }
68:     });
69:   }
70:   async request<T>(method: string, params: Record<string, unknown>): Promise<T> { await this.start(); return this.rpc<T>(method, params); }
