30: export async function handleAgentChat(request: Connect.IncomingMessage, response: ServerResponse, url: URL, chat: AgentChatService) {
31:   // Use the actual listening socket, not caller-controlled Host/forwarded headers.
32:   if (request.socket.localPort) chat.setMcpOrigin(`http://127.0.0.1:${request.socket.localPort}`);
33:   const route = url.pathname.slice('/api/mapping/agent-chat'.length);
34:   const binding = typeof request.headers['x-canvas-chat-binding'] === 'string' ? request.headers['x-canvas-chat-binding'] : '';
35:   if (route === '/tools' && request.method === 'GET') return sendJson(response, 200, await chat.toolDefinitions(binding));
36:   const tool = route.match(/^\/tools\/([A-Za-z0-9_-]+)$/);
37:   if (tool && request.method === 'POST') {
38:     const body = await readBody(request) as { input?: unknown; callId?: unknown };
39:     if (typeof body.callId !== 'string' || !body.callId || body.callId.length > 200)
40:       return sendJson(response, 400, { error: 'A tool call ID is required.' });
41:     return sendJson(response, 200, await chat.callBoundTool(binding, tool[1], body.input, body.callId));
42:   }
43:   if (route === '/generations' && request.method === 'GET') return sendJson(response, 200, await chat.generations(chatCanvasTargetSchema.parse({
44:     workspaceInstanceId: url.searchParams.get('workspaceInstanceId'), documentId: url.searchParams.get('documentId') })));
45:   if (route === '/info' && request.method === 'GET') return sendJson(response, 200, await chat.info());
46:   if (route === '/sessions/resume' && request.method === 'POST') return sendJson(response, 200, publicSession(await chat.resume(await readBody(request))));
47:   if (route === '/sessions') {
48:     if (request.method === 'GET') return sendJson(response, 200, await chat.list());
49:     if (request.method === 'POST') return sendJson(response, 200, publicSession(await chat.create(await readBody(request))));
50:   }
51:   const match = route.match(/^\/sessions\/([a-f0-9-]+)(?:\/(events|send|read-canvas|reload-tools|interrupt|answer|items|gen-alternatives|cancel-generation)(?:\/([^/]+))?)?$/);
52:   if (!match) return sendJson(response, 404, { error: 'Chat route not found' });
53:   const [, id, action, requestId] = match;
54:   if (request.method === 'GET' && !action) return sendJson(response, 200, publicSession(await chat.get(id)));
55:   if (request.method === 'GET' && action === 'items' && requestId) {
56:     const item = findChatItem(await chat.get(id), decodeURIComponent(requestId));
57:     return sendJson(response, item ? 200 : 404, item ?? { error: 'Chat activity not found' });
58:   }
59:   if (request.method === 'GET' && action === 'events') {
60:     await chat.get(id);
61:     if (response.destroyed) return;
62:     // Preview's compression middleware does not honor no-transform. Explicit identity
63:     // prevents gzip from holding the final records of a long-lived event stream.
64:     response.writeHead(200, { 'Content-Type': 'text/event-stream', 'Content-Encoding': 'identity', 'Cache-Control': 'no-cache, no-transform', Connection: 'keep-alive', 'X-Accel-Buffering': 'no' });
65:     response.flushHeaders();
66:     let unsubscribe = () => {};
67:     let snapshotAllowance = 0;
68:     response.on('drain', () => { snapshotAllowance = 0; });
69:     const heartbeat = setInterval(() => { response.write(': heartbeat\n\n'); }, 15_000);
70:     response.once('close', () => { clearInterval(heartbeat); unsubscribe(); });
71:     const writeEvent = (event: ChatEvent, snapshot = false) => {
72:       if (response.destroyed) return;
73:       const data = `data: ${JSON.stringify(event)}\n\n`;
74:       // A valid retained-history snapshot can exceed the live-event backlog limit.
75:       // Allow that single snapshot to drain; still bound additional queued events.
76:       // Otherwise large histories reconnect forever without ever receiving their snapshot.
77:       if (snapshot) snapshotAllowance += Buffer.byteLength(data);
78:       if (response.write(data)) snapshotAllowance = 0;
79:       else if (response.writableLength > snapshotAllowance + 2 * 1024 * 1024) response.destroy();
80:     };
81:     unsubscribe = await chat.subscribe(id, incoming => {
82:       const event = publicEvent(incoming);
83:       if (event.type !== 'snapshot') { writeEvent(event); return; }
84:       // Keep SSE records small. The client assembles parts before publishing once,
85:       // so reconnect never renders an incomplete transcript or parses a multi-MB line.
86:       const items = event.session.items.map(snapshotItem);
87:       if (items.length <= 1) { writeEvent({ ...event, session: { ...event.session, items } }, true); return; }
88:       writeEvent({ type: 'snapshot', session: { ...event.session, items: [] }, partial: true }, true);
89:       for (let start = 0; start < items.length && !response.destroyed; start++)
90:         writeEvent({ type: 'snapshot-part', items: [items[start]], final: start + 1 >= items.length }, true);
91:     });
92:     if (response.destroyed) { clearInterval(heartbeat); unsubscribe(); }
93:     return;
94:   }
95:   if (request.method === 'POST') {
96:     if (action === 'gen-alternatives') {
97:       const { canvas, ...input } = await readBody(request) as Record<string, unknown>;
98:       return sendJson(response, 200, await chat.genAlternatives(id, input, chatCanvasTargetSchema.parse(canvas)));
99:     }
100:     if (action === 'cancel-generation') await chat.cancelGeneration(id);
101:     else if (action === 'send') await chat.send(id, await readBody(request));
102:     else if (action === 'read-canvas') await chat.readCanvas(id, await readBody(request));
103:     else if (action === 'reload-tools') await chat.reloadTools(id);
104:     else if (action === 'interrupt') await chat.interrupt(id);
105:     else if (action === 'answer' && requestId) await chat.answer(id, requestId, await readBody(request));
106:     else return sendJson(response, 404, { error: 'Chat action not found' });
107:     return sendJson(response, 200, { ok: true });
108:   }
109:   return sendJson(response, 405, { error: 'method not allowed' });
110: }

