165:   private async highlight(name: 'highlight-node' | 'remove-highlights', raw: unknown, session: ChatToolSession) {
166:     if (session.settings.sandbox === 'read-only') throw Error('Highlights require Workspace access. Change Agent Chat access from Read only to Workspace.');
167:     const input = name === 'highlight-node' ? highlightSchema.parse(raw) : removeHighlightsSchema.parse(raw);
168:     if ((input.reference === undefined) === (input.nodeId === undefined)) throw Error('Specify either reference or nodeId.');
169:     if (input.reference !== undefined && ('contentNodeId' in input || 'contentNodeIds' in input)) throw Error('Use either selected reference nodes or explicit contentNodeId/contentNodeIds with nodeId.');
170:     const key = JSON.stringify([session.id, input.requestId]), signature = JSON.stringify([name, input]);
171:     let request = this.highlightRequests.get(key);
