175:       request = { signature, prepared: this.prepareHighlight(name, input, session).catch(error => { this.highlightRequests.delete(key); throw error; }) };
176:       this.highlightRequests.set(key, request);
177:     }
178:     const prepared = await request.prepared;
179:     const result = await this.agent.call('exec', prepared.input) as { transaction: CanvasMutationResult };
180:     return { documentId: prepared.documentId, version: result.transaction.version, nodeId: result.transaction.receipts[0]?.nodeId,
181:       highlights: result.transaction.receipts.filter(item => item.method === 'highlight' && item.highlightId)
