184:   private async prepareHighlight(name: string, input: z.infer<typeof highlightSchema> | z.infer<typeof removeHighlightsSchema>, session: ChatToolSession) {
185:     const reference = input.reference === undefined ? undefined : session.canvasContext?.references[input.reference - 1];
186:     if (input.reference !== undefined && !reference) throw Error('Reference unavailable. Select the target and send it with your message.');
187:     const canvas = reference?.canvas ?? session.canvasContext?.canvas;
188:     if (!canvas) throw Error('Open a live canvas and send another message or use Read Canvas.');
189:     const nodeId = reference?.displayNodeId ?? input.nodeId!;
190:     const snapshot = await this.agent.bridge.dispatch(canvas.workspaceInstanceId, { method: 'read', documentId: canvas.documentId, payload: { level: 'small', nodeIds: [nodeId] } }) as { version: number; nodes: { id: string; diagram?: { diagramId: string; revisionId: string }; content?: { structure: { nodes: Record<string, { id: string }> } } }[] };
