194:       throw Error('VERSION_CONFLICT: the referenced diagram changed. Reselect it and send the current reference.');
195:     const targets = reference?.reference.kind === 'nodes' ? reference.reference.nodeIds : highlightNodeIds('contentNodeId' in input || 'contentNodeIds' in input ? input : {});
