204:   }
205:   private async attachment(canvas: { workspaceInstanceId: string; documentId: string }) {
206:     const key = JSON.stringify(canvas);
207:     let attachment = this.attachments.get(key);
208:     if (!attachment) {
209:       attachment = this.agent.call('exec', { requestId: randomUUID(), code: `return canvas.attach(${JSON.stringify({ canvasId: canvas.workspaceInstanceId, documentId: canvas.documentId })});` })
210:         .then(result => (result as { value: { sessionId: string } }).value.sessionId)
211:         .catch(error => { this.attachments.delete(key); throw error; });
212:       this.attachments.set(key, attachment);
213:     }
214:     return attachment;
215:   }
216:   private async prepare(input: ChatDiagramInput, session: ChatToolSession, operation: DiagramTool): Promise<unknown> {
217:     const prepared: Record<string, unknown>[] = [];
218:     let canvas: { workspaceInstanceId: string; documentId: string } | undefined;
219:     let snapshot: LiveDocumentSnapshot | undefined;
220:     for (let index = 0; index < input.operations.length; index++) {
221:       try {
222:         let item = input.operations[index];
223:         if ((item.reference === undefined) === (item.nodeId === undefined)) throw Error('Specify either reference or nodeId');
224:         const reference = item.reference === undefined ? undefined : session.canvasContext?.references[item.reference - 1];
225:         if (item.reference !== undefined && !reference) throw Error('Reference unavailable; select it again');
226:         const target = reference?.canvas ?? session.canvasContext?.canvas;
227:         if (!target) throw Error('Open a live canvas and read it again');
228:         if (canvas && (canvas.workspaceInstanceId !== target.workspaceInstanceId || canvas.documentId !== target.documentId)) throw Error('Batch operations must target one canvas document');
229:         canvas = target;
230:         item = this.agent.resolveDiagramArguments(await this.attachment(canvas), item);
231:         snapshot ??= await this.agent.bridge.dispatch(canvas.workspaceInstanceId, { method: 'snapshot', documentId: canvas.documentId }) as LiveDocumentSnapshot;
232:         const nodeId = reference?.displayNodeId ?? item.nodeId!;
233:         const box = nodeId.startsWith('grid:') && findBox(snapshot.document.scene.root, nodeId.slice(5));
234:         const diagram = box && box.kind === 'diagram' ? snapshot.document.scene.contents[box.contentId] : undefined;
235:         const unanchored = operation === 'create-diagram' && nodeId === 'canvas';
236:         if (!diagram && !unanchored) throw Error('Target diagram unavailable');
237:         const baseRevisionId = reference?.reference.revisionId ?? item.baseRevisionId;
238:         if (reference && item.baseRevisionId && item.baseRevisionId !== reference.reference.revisionId) throw Error('VERSION_CONFLICT: baseRevisionId disagrees with the reference');
239:         if (!baseRevisionId || diagram && (baseRevisionId !== diagram.revisionId || reference && reference.reference.diagramId !== diagram.diagramId))
240:           throw Error('VERSION_CONFLICT: read the current diagram and supply its baseRevisionId');
241:         const { reference: _ref, contentNodeIds: _ids, ...fields } = item;
242:         let subtree: EditDiagramInput['subtree'], subtrees: EditDiagramInput['subtrees'];
243:         if (operation === 'edit-diagram' && 'replace-mode' in item && diagram) {
244:           let rootIds = item.contentNodeIds?.map(id => this.agent.projection.resolveAnchorId(id));
245:           if (reference?.reference.kind === 'nodes') {
246:             if (rootIds) throw Error('Use the reference selection or contentNodeIds, not both');
247:             if (item['replace-mode'] === 'diagram') throw Error('A node selection requires a subtree replace-mode');
248:             const ids = new Set(reference.reference.nodeIds), nodes = diagramContentNodes(diagram.content);
249:             const roots = nodes.filter(node => ids.has(node.id) && (!node.parentId || !ids.has(node.parentId)));
250:             const members = new Set(roots.flatMap(root => {
251:               const range = diagramSubtreeRange(diagram, root.id);
252:               return nodes.filter(node => node.line >= range.startLine && node.line <= range.endLine).map(node => node.id);
253:             }));
254:             if (!roots.length || members.size !== ids.size || [...members].some(id => !ids.has(id))) throw Error('Select complete subtrees without excluded nodes');
255:             rootIds = roots.map(root => root.id);
256:           }
257:           if (item['replace-mode'] === 'diagram' && rootIds) throw Error('diagram mode cannot include subtree targets');
258:           if (item['replace-mode'] === 'subnode-single' && rootIds?.length !== 1 && !(item.variant?.variantId && !rootIds)) throw Error('subnode-single requires one complete subtree');
259:           const targets = rootIds?.map(contentNodeId => ({ contentNodeId, revisionId: diagram.content.revisionId }));
260:           subtree = item['replace-mode'] === 'subnode-single' ? targets?.[0] : undefined;
261:           subtrees = item['replace-mode'].startsWith('multi-') ? targets : undefined;
262:           if (!item.variant?.variantId) diagramReplacementRanges(diagram, item['replace-mode'], subtree, subtrees);
263:         } else if (item.contentNodeIds) throw Error('contentNodeIds applies only to edit-diagram');
264:         prepared.push({ ...fields, nodeId, baseRevisionId, ...(subtree ? { subtree } : {}), ...(subtrees ? { subtrees } : {}) });
265:       } catch (error) { throw Error(`operations[${index}]: ${String(error)}`); }
266:     }
267:     return { sessionId: await this.attachment(canvas!), expectedVersion: snapshot!.version, requestId: randomUUID(), operations: prepared };
268:   }
