235:     preferredModel.current = model;
236:     setSettings(current => ({ ...current, model, effort: '' }));
237:     try { localStorage.setItem(modelStorageKey, model); } catch { /* Selection still works without browser storage. */ }
238:   };
239:   const model = info?.models.find(model => model.id === settings.model);
240:   const sidebarContent = <div className="agent-chat-sidebar-content">
241:     {info && <small className="agent-chat-account">{info.account}</small>}
242:     <div className="agent-chat-sessions"><select aria-label="Agent conversations" value={activeSessionId} disabled={busy} onChange={event => { if (event.target.value) activate(event.target.value); else newTab(); sidebar.close(); }}>
243:       <option value="">New conversation</option>{sessions.map(entry => <option key={entry.id} value={entry.id}>{entry.status === 'running' ? '● ' : ''}{entry.title}</option>)}
244:     </select><button disabled={busy} onClick={() => { newTab(); sidebar.close(); }}>New chat</button></div>
245:     <form className="agent-chat-resume" onSubmit={event => { event.preventDefault(); void resume(); }}>
246:       <label htmlFor={`${tabsId}-resume`}>Codex session ID</label>
247:       <input id={`${tabsId}-resume`} aria-describedby={`${tabsId}-resume-help`} value={resumeId} disabled={busy}
248:         placeholder="Paste session ID" autoComplete="off" spellCheck={false}
249:         onChange={event => { setResumeId(event.target.value); setResumeError(''); }} />
250:       <small id={`${tabsId}-resume-help`}>Resume a previous Codex session stored on this server, including CLI sessions.</small>
251:       <button disabled={!info || busy || !resumeId.trim()}>Resume session</button>
252:       {resumeError && <small className="agent-chat-reference-error" role="alert">{resumeError}</small>}
253:       {session && <small className="agent-chat-session-location" title={session.threadId}>{session.cwd}</small>}
254:     </form>
255:       {session && <div className="agent-chat-tool-reload">
256:         <button type="button" disabled={busy || running || !connected} onClick={() => void reloadTools()}
257:           title={running ? 'Wait for the current turn to finish' : 'Refresh available tools while keeping this conversation'}>Reload tools</button>
258:         {session.toolsReloadedAt && <small role="status">Tools reloaded. Ready for your next message.</small>}
259:       </div>}
260:       <div className="agent-chat-controls"><label>Model<select aria-label="Codex model" disabled={running || busy || !!session?.generation} value={settings.model} onChange={event => chooseModel(event.target.value)}>
261:         <option value="">Codex default</option>{settings.model && !model && <option value={settings.model}>{settings.model}</option>}{info?.models.map(model => <option key={model.id} value={model.id}>{model.name}</option>)}</select></label>
262:         <label>Effort<select aria-label="Reasoning effort" disabled={running || busy || !!session?.generation} value={settings.effort} onChange={event => setSettings(current => ({ ...current, effort: event.target.value as ChatSettings['effort'] }))}>
263:           <option value="">Default</option>{model?.efforts.map(effort => <option key={effort} value={effort}>{effort}</option>)}</select></label>
264:         <label>Access<select aria-label="Codex access" disabled={running || busy || !!session?.generation} value={settings.sandbox} onChange={event => setSettings(current => ({ ...current, sandbox: event.target.value as ChatSettings['sandbox'] }))}>
265:           <option value="danger-full-access">Full access (YOLO)</option><option value="workspace-write">Workspace</option><option value="read-only">Read only</option></select></label>
266:       </div>
267:   </div>;
268:   // The canvas SDK listens for clipboard events on document. Keep native text
269:   // copying/cutting inside the panel so selected shapes cannot replace its data.
270:   const content = <div className="agent-chat" style={{ '--agent-transcript-scale': zoom / 100 } as CSSProperties} data-chat-state={running ? 'running' : activeSessionId && !connected ? 'connecting' : session?.status ?? 'idle'} data-mapping-static-ui data-diagram-canvas-static-ui
271:     onCopy={event => event.stopPropagation()} onCut={event => event.stopPropagation()}
272:     onKeyDown={event => { if (event.key !== 'Escape') event.stopPropagation(); }}>
273:     {sidebar.element && createPortal(sidebarContent, sidebar.element)}
274:     <div className="agent-chat-tabbar">
275:       <div ref={tabList} className="agent-chat-tabs" role="tablist" aria-label="Agent Chat conversations">
276:         {tabs.ids.map((id, index) => {
277:           const summary = sessions.find(entry => entry.id === id);
278:           const label = summary?.title || 'New chat';
279:           return <div className="agent-chat-tab" key={id} data-active={selected === id}>
280:             <button type="button" role="tab" id={`${tabsId}-${id}`} aria-controls={`${tabsId}-panel`} aria-selected={selected === id}
281:               tabIndex={selected === id ? 0 : -1} disabled={busy} title={label} onClick={() => activate(id)}
282:               onKeyDown={event => {
283:                 if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
284:                 event.preventDefault();
285:                 const next = tabs.ids[event.key === 'Home' ? 0 : event.key === 'End' ? tabs.ids.length - 1 : (index + (event.key === 'ArrowLeft' ? -1 : 1) + tabs.ids.length) % tabs.ids.length];
286:                 activate(next); requestAnimationFrame(() => document.getElementById(`${tabsId}-${next}`)?.focus());
287:               }}><span>{summary?.status === 'running' ? '● ' : ''}{label}</span></button>
288:             <button type="button" className="agent-chat-tab-close" aria-label={`Close chat tab: ${label}`} title="Close tab (keeps conversation in history)" disabled={busy} onClick={() => closeTab(id)}>×</button>
289:           </div>;
290:         })}
291:       </div>
292:       <button type="button" className="agent-chat-new-tab" aria-label="New chat tab" title="New chat (Ctrl+B, C)" disabled={!info || busy} onClick={newTab}>+</button>
293:     </div>
294:     <div className="agent-chat-tab-content" role="tabpanel" id={`${tabsId}-panel`} aria-labelledby={`${tabsId}-${selected}`}>
295:     {error && <div className="agent-chat-error" role="alert">{error}{!info && <button onClick={() => setAttempt(value => value + 1)}>Retry connection</button>}</div>}
296:     {session?.items.length ? <ChatTranscript key={session.id} session={session} open={open} zoom={zoom} onZoomChange={setZoom} /> : <div className="agent-chat-timeline"><div className="agent-chat-empty"><span>CODEX</span><h2>What would you like to work on?</h2><p>Ask about your project, explore code, or make a change.</p>{info && <code>{info.cwd}</code>}</div></div>}
297:     <div className="agent-chat-requests">{session?.pending.map(request => <PendingRequest key={request.id} request={request} onAnswer={answer => chatRequest(`/sessions/${selected}/answer/${request.id}`, answer)} />)}</div>
298:     <div>{session?.generation && <p className="agent-chat-context">Generation chat · {session.generation.metadata.status}. Start another generation from the canvas to iterate.</p>}</div>
299:     <form className="agent-chat-composer" onSubmit={event => { event.preventDefault(); void send(); }}>
300:       {running && <ChatWorking key={session.id} startedAt={session.turnStartedAt} open={open} waiting={session.pending.length > 0} activity={session.activity} />}
301:       {session && !session.canvasTools && <small className="agent-chat-tool-hint">Start a new chat to enable diagram editing tools.</small>}
302:       {referenceError && <small className="agent-chat-reference-error" role="alert">{referenceError}</small>}
303:       <ChatPromptEditor value={draft} draftKey={selected} selectedReferences={selectedReferences} open={open} disabled={!info || busy || !!session?.generation}
304:         onChange={value => setDrafts(current => ({ ...current, [selected]: value }))} onSend={() => void send()} />
305:       <div className="agent-chat-composer-actions">
306:       <button type="button" className="agent-chat-read-canvas" disabled={!!session?.generation || !canvasTarget || busy || running || !info || (!!activeSessionId && (!session || !connected))}
307:         title={canvasTarget ? 'Send the current canvas to the agent' : 'Open a live canvas to read it'} onClick={() => void readCanvas()}>Read Canvas</button>
308:         {running ? <button type="button" className="agent-chat-send" disabled={busy} onClick={() => void stop()}>Stop</button> : <button className="agent-chat-send" disabled={!!session?.generation || busy || !!referenceError || !text.trim() || !info || (!!activeSessionId && (!session || !connected))}>{busy ? 'Starting…' : 'Send ↑'}</button>}
309:       </div>
310:     </form>
311:     </div>
312:   </div>;
313:   return <MarkdownActivityContext.Provider value={open}><ChatCanvasCopyContext.Provider value={onCopyDiagram}>
314:     <ChatHighlightContext.Provider value={onHighlightReference}><ChatFileLinks cwd={session?.cwd || info?.cwd || ''} projectId={projectId}>{content}</ChatFileLinks></ChatHighlightContext.Provider>
315:   </ChatCanvasCopyContext.Provider></MarkdownActivityContext.Provider>;
316: }
